import heapq

def most_on_time(tasks: list[list[int]]) -> int:
    day, kept = 0, []                    # kept: max-heap of durations (negated)
    for duration, deadline in sorted(tasks, key=lambda t: t[1]):
        day += duration
        heapq.heappush(kept, -duration)
        if day > deadline:               # late: drop the longest task kept, maybe this one
            day += heapq.heappop(kept)
    return len(kept)

perf.naive:
def most_on_time(tasks: list[list[int]]) -> int:
    tasks = sorted(tasks, key=lambda t: t[1])
    horizon = max((deadline for _, deadline in tasks), default=0)
    best = [-1] * (horizon + 1)          # best[d]: most tasks kept that use exactly d days
    best[0] = 0
    for duration, deadline in tasks:     # knapsack over days, in deadline order
        for d in range(deadline, duration - 1, -1):
            if best[d - duration] >= 0 and best[d - duration] + 1 > best[d]:
                best[d] = best[d - duration] + 1
    return max(best)
